/**
 * 滑動條組件基類
 *
 * 提供滑動條的基本功能：
 * - 拖拽交互
 * - 值變化通知
 * - 可視化軌道和滑塊
 */

import { Component, ComponentOptions } from './Component';
import type { MpvVideoElement } from '../renderer/ui/MpvVideoElement';

/**
 * 滑動條配置選項
 */
export interface SliderOptions extends ComponentOptions {
    /** 最小值 */
    min?: number;

    /** 最大值 */
    max?: number;

    /** 初始值 */
    value?: number;

    /** 步進值 */
    step?: number;

    /** 是否垂直方向 */
    vertical?: boolean;

    /** 值變化回調 */
    onChange?: (value: number) => void;

    /** 拖拽開始回調 */
    onDragStart?: (value: number) => void;

    /** 拖拽結束回調 */
    onDragEnd?: (value: number) => void;
}

/**
 * 滑動條組件基類
 */
export abstract class Slider extends Component {
    static componentName = 'slider';

    protected options: SliderOptions;

    /** 當前值 */
    protected value: number;

    /** 是否正在拖拽 */
    protected isDragging = false;

    /** 軌道元素 */
    protected trackEl: HTMLElement;

    /** 已填充軌道元素 */
    protected trackFilledEl: HTMLElement;

    /** 滑塊元素 */
    protected handleEl: HTMLElement;

    constructor(player: MpvVideoElement, options: SliderOptions = {}) {
        super(player, {
            className: 'mpv-slider',
            ...options,
        });
        this.options = {
            min: 0,
            max: 100,
            value: 0,
            step: 1,
            vertical: false,
            ...options,
        };
        this.value = this.options.value!;

        // 獲取子元素引用
        this.trackEl = this.el.querySelector('.mpv-slider-track')!;
        this.trackFilledEl = this.el.querySelector('.mpv-slider-track-filled')!;
        this.handleEl = this.el.querySelector('.mpv-slider-handle')!;

        // 綁定事件
        this.bindEvents();

        // 初始化視覺狀態
        this.updateVisualState();
    }

    /**
     * 創建滑動條元素
     */
    protected createEl(): HTMLElement {
        const container = document.createElement('div');
        container.className = `mpv-slider${this.options.vertical ? ' mpv-slider-vertical' : ''}`;

        container.innerHTML = `
            <div class="mpv-slider-track">
                <div class="mpv-slider-track-filled"></div>
            </div>
            <div class="mpv-slider-handle"></div>
        `;

        return container;
    }

    /**
     * 綁定交互事件
     */
    private bindEvents(): void {
        // 軌道點擊
        this.listen(this.trackEl, 'click', this.onTrackClick.bind(this));

        // 滑塊拖拽
        this.listen(this.handleEl, 'mousedown', this.onDragStart.bind(this));
        this.listen(this.el, 'mousedown', this.onDragStart.bind(this));
    }

    /**
     * 軌道點擊處理
     */
    private onTrackClick(event: MouseEvent): void {
        if (this.isDragging) return;

        const rect = this.trackEl.getBoundingClientRect();
        const value = this.calculateValueFromPosition(event, rect);
        this.setValue(value, true);
    }

    /**
     * 拖拽開始
     */
    private onDragStart(event: MouseEvent): void {
        event.preventDefault();
        this.isDragging = true;
        this.addClass('dragging');

        // 計算初始值
        const rect = this.trackEl.getBoundingClientRect();
        const value = this.calculateValueFromPosition(event, rect);
        this.setValue(value, false);

        this.options.onDragStart?.(this.value);

        // 綁定全局移動和釋放事件
        const onMove = (e: MouseEvent) => {
            const v = this.calculateValueFromPosition(e, rect);
            this.setValue(v, false);
        };

        const onEnd = () => {
            this.isDragging = false;
            this.removeClass('dragging');
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('mouseup', onEnd);

            this.options.onDragEnd?.(this.value);
            this.options.onChange?.(this.value);
        };

        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onEnd);
    }

    /**
     * 根據滑鼠位置計算值
     */
    private calculateValueFromPosition(event: MouseEvent, rect: DOMRect): number {
        const { min, max, vertical } = this.options;
        let ratio: number;

        if (vertical) {
            ratio = 1 - (event.clientY - rect.top) / rect.height;
        } else {
            ratio = (event.clientX - rect.left) / rect.width;
        }

        ratio = Math.max(0, Math.min(1, ratio));
        return min! + ratio * (max! - min!);
    }

    /**
     * 設置值
     */
    setValue(value: number, notify = true): void {
        const { min, max, step } = this.options;

        // 限制範圍
        value = Math.max(min!, Math.min(max!, value));

        // 步進對齊
        if (step! > 0) {
            value = Math.round(value / step!) * step!;
        }

        if (this.value !== value) {
            this.value = value;
            this.updateVisualState();

            if (notify) {
                this.options.onChange?.(value);
            }
        }
    }

    /**
     * 獲取當前值
     */
    getValue(): number {
        return this.value;
    }

    /**
     * 獲取值的百分比 (0-1)
     */
    getPercentage(): number {
        const { min, max } = this.options;
        return (this.value - min!) / (max! - min!);
    }

    /**
     * 更新視覺狀態
     */
    protected updateVisualState(): void {
        const percentage = this.getPercentage() * 100;

        if (this.options.vertical) {
            this.trackFilledEl.style.height = `${percentage}%`;
            this.handleEl.style.bottom = `${percentage}%`;
        } else {
            this.trackFilledEl.style.width = `${percentage}%`;
            this.handleEl.style.left = `${percentage}%`;
        }
    }

    /**
     * 是否正在拖拽
     */
    dragging(): boolean {
        return this.isDragging;
    }
}
