/**
 * 按鈕組件基類
 *
 * 提供按鈕的基本功能：
 * - 點擊處理
 * - 狀態圖標切換
 * - 快捷鍵支援
 */

import { Component, ComponentOptions } from './Component';
import type { MpvVideoElement } from '../renderer/ui/MpvVideoElement';

/**
 * 按鈕配置選項
 */
export interface ButtonOptions extends ComponentOptions {
    /** 按鈕文字（無圖標時顯示） */
    text?: string;

    /** 圖標 HTML（SVG 或 img） */
    icon?: string;

    /** 替代圖標（用於狀態切換） */
    iconAlt?: string;

    /** ARIA 標籤 */
    ariaLabel?: string;

    /** 是否禁用 */
    disabled?: boolean;

    /** 點擊回調（簡化使用） */
    onClick?: (event: MouseEvent) => void;
}

/**
 * 按鈕組件基類
 */
export abstract class Button extends Component {
    static componentName = 'button';

    protected options: ButtonOptions;

    /** 當前顯示的是替代圖標 */
    private isAltIcon = false;

    constructor(player: MpvVideoElement, options: ButtonOptions = {}) {
        super(player, options);
        this.options = options;

        // 綁定點擊事件
        this.on('click', this.onClickInternal.bind(this));

        // 初始禁用狀態
        if (options.disabled) {
            this.disable();
        }
    }

    /**
     * 創建按鈕元素
     */
    protected createEl(): HTMLElement {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'mpv-btn';

        // 設置圖標或文字
        if (this.options.icon) {
            button.innerHTML = this.options.icon;
        } else if (this.options.text) {
            button.textContent = this.options.text;
        }

        // 設置 ARIA 標籤
        if (this.options.ariaLabel) {
            button.setAttribute('aria-label', this.options.ariaLabel);
        }

        return button;
    }

    /**
     * 內部點擊處理
     */
    private onClickInternal(event: MouseEvent): void {
        if (this.isDisabled()) {
            event.preventDefault();
            event.stopPropagation();
            return;
        }

        // 調用子類的點擊處理
        this.handleClick(event);

        // 調用配置的回調
        this.options.onClick?.(event);
    }

    /**
     * 子類可重寫：處理點擊事件
     */
    protected handleClick(_event: MouseEvent): void {
        // 子類實現
    }

    /**
     * 設置按鈕圖標
     */
    setIcon(iconHtml: string): void {
        this.el.innerHTML = iconHtml;
    }

    /**
     * 切換圖標
     */
    toggleIcon(showAlt: boolean): void {
        const icon = showAlt ? this.options.iconAlt : this.options.icon;
        if (icon && this.isAltIcon !== showAlt) {
            this.el.innerHTML = icon;
            this.isAltIcon = showAlt;
        }
    }

    /**
     * 切換到替代圖標
     */
    showAltIcon(): void {
        this.toggleIcon(true);
    }

    /**
     * 切換到主圖標
     */
    showMainIcon(): void {
        this.toggleIcon(false);
    }

    /**
     * 設置按鈕文字
     */
    setText(text: string): void {
        this.el.textContent = text;
    }

    /**
     * 設置按鈕標題（tooltip）
     */
    setTitle(title: string): void {
        this.el.title = title;
    }

    /**
     * 設置活動狀態
     */
    setActive(active: boolean): void {
        this.toggleClass('active', active);
    }

    /**
     * 是否處於活動狀態
     */
    isActive(): boolean {
        return this.hasClass('active');
    }
}

/**
 * 切換按鈕
 * 有兩個狀態，點擊切換
 */
export abstract class ToggleButton extends Button {
    /** 當前是否處於「開」狀態 */
    protected toggled = false;

    /**
     * 子類實現：獲取當前狀態
     */
    protected abstract isToggled(): boolean;

    /**
     * 子類實現：執行切換操作
     */
    protected abstract toggle(): void;

    protected handleClick(_event: MouseEvent): void {
        this.toggle();
    }

    /**
     * 更新視覺狀態
     */
    protected updateVisualState(): void {
        const toggled = this.isToggled();
        this.toggled = toggled;
        this.toggleIcon(toggled);
        this.setActive(toggled);
    }
}
