/**
 * 基礎 UI 組件類
 *
 * 所有控制列組件和 UI 元素的基類
 * 借鏡 Video.js 的 Component 設計模式
 */

import type { MpvVideoElement } from '../renderer/ui/MpvVideoElement';
import type { MediaState, MediaStateKey } from '../core/types/state';
import type { MediaEventMap, MediaEventType, EventUnsubscribe } from '../core/types/events';

/**
 * 組件配置選項
 */
export interface ComponentOptions {
    /** CSS 類名 */
    className?: string;

    /** 標題（tooltip） */
    title?: string;

    /** 是否可見，默認 true */
    visible?: boolean;

    /** 額外的 CSS 樣式 */
    style?: Partial<CSSStyleDeclaration>;

    /** 額外配置 */
    [key: string]: unknown;
}

/**
 * 所有 UI 組件的抽象基類
 *
 * 提供：
 * - DOM 元素創建和管理
 * - 播放器狀態訂閱
 * - 事件監聽和自動清理
 * - 生命週期管理
 */
export abstract class Component {
    /** 組件名稱（用於註冊和識別） */
    static componentName: string = 'component';

    /** 播放器實例引用 */
    protected player: MpvVideoElement;

    /** 根 DOM 元素 */
    protected el: HTMLElement;

    /** 組件配置 */
    protected options: ComponentOptions;

    /** 清理函數列表（事件監聽、狀態訂閱等） */
    private cleanups: Array<() => void> = [];

    /** 是否已銷毀 */
    private destroyed = false;

    constructor(player: MpvVideoElement, options: ComponentOptions = {}) {
        this.player = player;
        this.options = options;

        // 創建 DOM 元素
        this.el = this.createEl();

        // 應用 className
        if (options.className) {
            this.el.classList.add(...options.className.split(' '));
        }

        // 應用 title
        if (options.title) {
            this.el.title = options.title;
        }

        // 應用 style
        if (options.style) {
            Object.assign(this.el.style, options.style);
        }

        // 應用 visible
        if (options.visible === false) {
            this.hide();
        }
    }

    /**
     * 子類必須實現：創建根 DOM 元素
     */
    protected abstract createEl(): HTMLElement;

    /**
     * 獲取根元素
     */
    getEl(): HTMLElement {
        return this.el;
    }

    /**
     * 獲取組件名稱
     */
    getName(): string {
        return (this.constructor as typeof Component).componentName;
    }

    // ===== 狀態訂閱 =====

    /**
     * 訂閱播放器狀態變化
     * 自動在組件銷毀時取消訂閱
     *
     * @param key - 狀態鍵
     * @param callback - 狀態變化回調
     * @param immediate - 是否立即執行一次
     */
    protected subscribeState<K extends MediaStateKey>(
        key: K,
        callback: (value: MediaState[K] extends { get(): infer V } ? V : never) => void,
        _immediate = true
    ): void {
        // 訪問播放器的 state 屬性
        const state = (this.player as unknown as { state: MediaState }).state;
        if (!state || !(key in state)) {
            console.warn(`[Component] State "${key}" not found`);
            return;
        }

        const signal = state[key];
        if (signal && typeof signal.subscribe === 'function') {
            const unsubscribe = signal.subscribe(callback as (value: unknown, prev: unknown) => void);
            this.cleanups.push(unsubscribe);
        }
    }

    // ===== 事件監聽 =====

    /**
     * 監聽播放器事件
     * 自動在組件銷毀時取消監聽
     *
     * @param event - 事件名稱
     * @param handler - 事件處理器
     */
    protected onPlayerEvent<K extends MediaEventType>(
        event: K,
        handler: (data: MediaEventMap[K]) => void
    ): void {
        // 使用播放器的 on 方法（需要在 MpvVideoElement 中實現）
        const playerAny = this.player as unknown as {
            on(event: string, handler: (data: unknown) => void): EventUnsubscribe;
        };

        if (typeof playerAny.on === 'function') {
            const unsubscribe = playerAny.on(event, handler as (data: unknown) => void);
            this.cleanups.push(unsubscribe);
        } else {
            // 降級到 DOM 事件
            const domHandler = (e: Event) => {
                handler((e as CustomEvent).detail);
            };
            this.player.addEventListener(event, domHandler);
            this.cleanups.push(() => this.player.removeEventListener(event, domHandler));
        }
    }

    /**
     * 監聽 DOM 事件
     * 自動在組件銷毀時取消監聽
     *
     * @param target - 事件目標
     * @param event - 事件名稱
     * @param handler - 事件處理器
     * @param options - 事件選項
     */
    protected listen<K extends keyof HTMLElementEventMap>(
        target: HTMLElement | Window | Document,
        event: K,
        handler: (e: HTMLElementEventMap[K]) => void,
        options?: AddEventListenerOptions
    ): void {
        target.addEventListener(event, handler as EventListener, options);
        this.cleanups.push(() =>
            target.removeEventListener(event, handler as EventListener, options)
        );
    }

    /**
     * 監聯自身元素的 DOM 事件
     */
    protected on<K extends keyof HTMLElementEventMap>(
        event: K,
        handler: (e: HTMLElementEventMap[K]) => void,
        options?: AddEventListenerOptions
    ): void {
        this.listen(this.el, event, handler, options);
    }

    // ===== 顯示/隱藏 =====

    /**
     * 顯示組件
     */
    show(): void {
        this.el.hidden = false;
    }

    /**
     * 隱藏組件
     */
    hide(): void {
        this.el.hidden = true;
    }

    /**
     * 切換顯示/隱藏
     */
    toggleVisibility(): void {
        if (this.el.hidden) {
            this.show();
        } else {
            this.hide();
        }
    }

    /**
     * 是否可見
     */
    isVisible(): boolean {
        return !this.el.hidden;
    }

    // ===== 啟用/禁用 =====

    /**
     * 啟用組件
     */
    enable(): void {
        this.el.classList.remove('disabled');
        if (this.el instanceof HTMLButtonElement) {
            this.el.disabled = false;
        }
    }

    /**
     * 禁用組件
     */
    disable(): void {
        this.el.classList.add('disabled');
        if (this.el instanceof HTMLButtonElement) {
            this.el.disabled = true;
        }
    }

    /**
     * 是否已禁用
     */
    isDisabled(): boolean {
        return this.el.classList.contains('disabled');
    }

    // ===== 樣式操作 =====

    /**
     * 添加 CSS 類
     */
    addClass(...classNames: string[]): void {
        this.el.classList.add(...classNames);
    }

    /**
     * 移除 CSS 類
     */
    removeClass(...classNames: string[]): void {
        this.el.classList.remove(...classNames);
    }

    /**
     * 切換 CSS 類
     */
    toggleClass(className: string, force?: boolean): boolean {
        return this.el.classList.toggle(className, force);
    }

    /**
     * 檢查是否包含 CSS 類
     */
    hasClass(className: string): boolean {
        return this.el.classList.contains(className);
    }

    // ===== 定時器 =====

    /**
     * 設置 setTimeout，自動在銷毀時清理
     */
    protected setTimeout(callback: () => void, delay: number): number {
        const id = window.setTimeout(callback, delay);
        this.cleanups.push(() => clearTimeout(id));
        return id;
    }

    /**
     * 設置 setInterval，自動在銷毀時清理
     */
    protected setInterval(callback: () => void, interval: number): number {
        const id = window.setInterval(callback, interval);
        this.cleanups.push(() => clearInterval(id));
        return id;
    }

    /**
     * 設置 requestAnimationFrame，自動在銷毀時清理
     */
    protected requestAnimationFrame(callback: FrameRequestCallback): number {
        const id = window.requestAnimationFrame(callback);
        this.cleanups.push(() => cancelAnimationFrame(id));
        return id;
    }

    // ===== 生命週期 =====

    /**
     * 銷毀組件
     * 清理所有資源、事件監聽和 DOM 元素
     */
    destroy(): void {
        if (this.destroyed) {
            return;
        }
        this.destroyed = true;

        // 執行所有清理函數
        for (const cleanup of this.cleanups) {
            try {
                cleanup();
            } catch (error) {
                console.error(`[Component] Cleanup error:`, error);
            }
        }
        this.cleanups = [];

        // 移除 DOM 元素
        this.el.remove();
    }

    /**
     * 是否已銷毀
     */
    isDestroyed(): boolean {
        return this.destroyed;
    }
}
